    fn action_lane_len(&self) -> usize {
        let runtime_lane = self
            .host_runtime
            .as_ref()
            .map(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => runtime.action_lane_count(),
                NativeHostRuntimeAttachment::Client(runtime) => runtime.action_lane_count(),
            })
            .unwrap_or(0);
        action_lane_total(
            runtime_lane,
            self.pending_host_actions.len(),
            usize::from(self.retained_action_overflow.is_some()),
        )
    }

    fn rebind_pending_host_actions(
        &mut self,
        epochs: NativeHostRuntimeEpochs,
        navigation_epoch: u64,
    ) {
        for action in &mut self.pending_host_actions {
            action.rebind_transport_epochs(epochs, navigation_epoch);
        }
        if let Some(action) = self.retained_action_overflow.as_mut() {
            action.rebind_transport_epochs(epochs, navigation_epoch);
        }
        if let Some(runtime) = self.host_runtime.as_mut() {
            match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => {
                    runtime.rebind_pending(epochs, navigation_epoch)
                }
                NativeHostRuntimeAttachment::Client(runtime) => {
                    runtime.rebind_pending(epochs, navigation_epoch)
                }
            }
        }
    }

    fn rebind_pending_client_epoch(&mut self, client_epoch: u64) {
        for action in &mut self.pending_host_actions {
            action.client_epoch = client_epoch;
        }
        if let Some(action) = self.retained_action_overflow.as_mut() {
            action.client_epoch = client_epoch;
        }
    }

    /// Reconcile retained actions only at an explicit caller boundary.
    /// Controller ticks observe outcomes and transport state but never
    /// resubmit a failed or uncertain command on their own.
    pub fn reconcile_pending_host_actions(&mut self, max: usize) {
        self.flush_provider_settings_pending();
        for _ in 0..max.min(MAX_ACTION_LANE_RECORDS) {
            let from_overflow = self.pending_host_actions.is_empty();
            let Some(action) = self
                .pending_host_actions
                .front()
                .cloned()
                .or_else(|| self.retained_action_overflow.clone())
            else {
                break;
            };
            if !self.interaction.accepts_action_record(&action) {
                if is_native_query_command(&action.command) {
                    self.discard_native_query_action(&action);
                    continue;
                }
                self.set_transport_failure(&action, NativeHostActionResult::Stale);
                break;
            }
            match self.try_enqueue_host_action(action.clone()) {
                NativeHostActionResult::Queued => {
                    if from_overflow {
                        self.retained_action_overflow = None;
                    } else {
                        let _ = self.pending_host_actions.pop_front();
                    }
                    self.clear_recovered_action_failure();
                }
                result @ (NativeHostActionResult::Disconnected
                | NativeHostActionResult::QueueFull
                | NativeHostActionResult::Stale) => {
                    if is_native_query_command(&action.command) {
                        self.settle_native_query_admission_failure(&action, result);
                        continue;
                    }
                    self.set_transport_failure(&action, result);
                    break;
                }
            }
        }
    }

    fn retain_pending_host_action(&mut self, action: NativeActionRecord) -> bool {
        if self
            .pending_host_actions
            .iter()
            .any(|pending| same_native_action_identity(pending, &action))
            || self
                .retained_action_overflow
                .as_ref()
                .is_some_and(|pending| same_native_action_identity(pending, &action))
        {
            return true;
        }
        if self.action_lane_len() >= MAX_ACTION_LANE_RECORDS {
            return false;
        }
        if self.pending_host_actions.len() < MAX_RETRY_HOST_ACTIONS {
            self.pending_host_actions.push_back(action);
            true
        } else if self.retained_action_overflow.is_none() {
            self.retained_action_overflow = Some(action);
            true
        } else {
            false
        }
    }

    fn discard_native_query_action(&mut self, action: &NativeActionRecord) {
        if let Some((_, task_id, TaskCockpitQuery::Conversation { .. })) =
            Self::task_cockpit_command_parts(&action.command)
        {
            self.task_surfaces
                .cancel_conversation(task_id, action.request_generation);
        }
        let request_id = native_request_id(&action.command);
        self.pending_host_actions
            .retain(|pending| native_request_id(&pending.command) != request_id);
        if self
            .retained_action_overflow
            .as_ref()
            .is_some_and(|pending| native_request_id(&pending.command) == request_id)
        {
            self.retained_action_overflow = None;
        }
        if self.last_action_failure.as_ref().is_some_and(|failure| {
            failure.action_id() == action.id && failure.command_id().is_none()
        }) {
            self.last_action_failure = None;
            self.restore_connected_host_state();
        }
    }

    fn settle_native_query_failure(&mut self, action: &NativeActionRecord, error: String) {
        if is_agent_connection_query_command(&action.command) {
            self.agent_connection = Some(agent_connection_snapshot(AgentPresence::CheckFailed));
        }
        if matches!(
            &action.command,
            NativeHostCommand::ProviderSettingsQuery { .. }
        ) {
            if let Some(ctl) = self.provider_settings.as_mut() {
                ctl.clear_pending_on_queue_failure();
            }
        }
        if let Some((_, task_id, TaskCockpitQuery::Terminal)) =
            Self::task_cockpit_command_parts(&action.command)
        {
            self.task_surfaces.note_terminal_reconnecting(task_id);
            if self.interaction.selected_task() == Some(task_id) {
                self.sync_terminal_from_cockpit();
            }
        }
        self.fail_header_commit_from_action(action, format!("Commit failed: {error}"));
        self.discard_native_query_action(action);
        self.last_query_detail = Some(error);
    }

    fn settle_native_query_admission_failure(
        &mut self,
        action: &NativeActionRecord,
        result: NativeHostActionResult,
    ) {
        let detail = match result {
            NativeHostActionResult::Disconnected => "host query not sent: disconnected",
            NativeHostActionResult::QueueFull => "host query not sent: host is busy",
            NativeHostActionResult::Stale => "host query superseded before it was sent",
            NativeHostActionResult::Queued => return,
        };
        if let Some((_, task_id, TaskCockpitQuery::Terminal)) =
            Self::task_cockpit_command_parts(&action.command)
        {
            self.task_surfaces.note_terminal_reconnecting(task_id);
            if self.interaction.selected_task() == Some(task_id) {
                self.sync_terminal_from_cockpit();
            }
        }
        self.fail_header_commit_from_action(action, format!("Commit failed: {detail}"));
        self.discard_native_query_action(action);
        self.last_query_detail = Some(detail.to_string());
        self.restore_connected_host_state();
    }

    fn settle_native_query_request_capacity_failure(&mut self) {
        self.last_query_detail = Some("host query not sent: host is busy".to_string());
        self.restore_connected_host_state();
    }

    fn try_enqueue_host_action(&mut self, record: NativeActionRecord) -> NativeHostActionResult {
        match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Client(runtime)) => runtime.enqueue(record),
            Some(NativeHostRuntimeAttachment::Injected(runtime)) => runtime.enqueue(record),
            None => NativeHostActionResult::Disconnected,
        }
    }

    fn set_transport_failure(
        &mut self,
        action: &NativeActionRecord,
        result: NativeHostActionResult,
    ) {
        let failure = match result {
            NativeHostActionResult::Disconnected => NativeHostActionFailure::Disconnected {
                action_id: action.id,
            },
            NativeHostActionResult::QueueFull => NativeHostActionFailure::QueueFull {
                action_id: action.id,
            },
            NativeHostActionResult::Stale => NativeHostActionFailure::Stale {
                action_id: action.id,
                command_id: native_command_id(&action.command),
            },
            NativeHostActionResult::Queued => return,
        };
        self.host_state = match &failure {
            NativeHostActionFailure::Disconnected { .. } => NativeHostState::Disconnected,
            NativeHostActionFailure::QueueFull { .. } | NativeHostActionFailure::Stale { .. } => {
                match &self.host_state {
                    NativeHostState::Connected { .. } => self.host_state.clone(),
                    _ => self
                        .host_runtime
                        .as_ref()
                        .map(|runtime| match runtime {
                            NativeHostRuntimeAttachment::Injected(runtime) => runtime.host_state(),
                            NativeHostRuntimeAttachment::Client(runtime) => runtime.host_state(),
                        })
                        .unwrap_or(self.host_state.clone()),
                }
            }
            _ => NativeHostState::Error {
                message: bounded_host_error(failure.retry_message()),
            },
        };
        self.last_action_failure = Some(failure);
    }

    fn set_action_capacity_failure(&mut self, action_id: &'static str) {
        let failure = NativeHostActionFailure::QueueFull { action_id };
        self.host_state = NativeHostState::Error {
            message: bounded_host_error(failure.retry_message()),
        };
        self.last_action_failure = Some(failure);
    }

    fn set_execution_failure(
        &mut self,
        action: &NativeActionRecord,
        error: String,
        uncertain: bool,
    ) {
        let command_id = native_command_id(&action.command);
        let failure = if uncertain {
            NativeHostActionFailure::ExecutionUncertain {
                action_id: action.id,
                command_id,
                message: bounded_host_error(error),
            }
        } else {
            NativeHostActionFailure::ExecutionFailed {
                action_id: action.id,
                command_id,
                message: bounded_host_error(error),
            }
        };
        self.host_state = NativeHostState::Error {
            message: bounded_host_error(failure.retry_message()),
        };
        self.last_action_failure = Some(failure);
    }

    fn apply_epoch_fenced_action_outcome(&mut self, outcome: NativeHostActionOutcome) {
        let action = outcome.action().clone();
        if self.is_retired_delete_flow_command(&action) {
            if let Some(command_id) = native_command_id(&action.command) {
                self.discard_host_action_by_command_id(command_id);
                self.retired_delete_flow_commands
                    .retain(|id| *id != command_id);
            }
            return;
        }
        if self.matches_live_delete_flow_command(&action) {
            // The command's own committed mutation can advance the task revision
            // (or remove the task) before its receipt arrives. The still-live
            // confirmation owns this exact command, independently of UI focus.
            let epochs = self.interaction.action_epochs();
            if action.connection_epoch == epochs.connection_epoch
                && action.resource_generation == epochs.resource_generation
                && action.runtime_generation == epochs.runtime_generation
                && action.client_epoch <= epochs.client_epoch
            {
                self.apply_action_outcome(outcome);
            } else {
                self.settle_delete_flow_outcome(
                    &action,
                    DeleteFlowSettleKind::Stale {
                        message:
                            "The connection changed. Check the task before trying Delete again."
                                .into(),
                    },
                );
            }
            return;
        }
        let accepted = if is_global_native_query_command(&action.command) {
            self.interaction
                .accepts_global_query_outcome_record(&action)
        } else {
            self.interaction.accepts_action_outcome_record(&action)
        };
        if !accepted {
            if is_native_query_command(&action.command) {
                self.discard_native_query_action(&action);
                return;
            }
            if self.settle_delete_flow_outcome(
                &action,
                DeleteFlowSettleKind::Stale {
                    message: "the task changed before the delete finished".into(),
                },
            ) {
                return;
            }
            if self.retain_pending_host_action(action.clone()) {
                self.set_transport_failure(&action, NativeHostActionResult::Stale);
            } else {
                self.set_action_capacity_failure(action.id);
            }
            return;
        }
        self.apply_action_outcome(outcome);
    }

    fn apply_action_outcome(&mut self, outcome: NativeHostActionOutcome) {
        match outcome {
            NativeHostActionOutcome::Accepted { action, receipt } => {
                let action_id = action.id;
                let command_id = native_command_id(&action.command);
                if self.matches_live_delete_flow_command(&action)
                    && command_id != Some(receipt.command_id())
                {
                    self.settle_delete_flow_outcome(
                        &action,
                        DeleteFlowSettleKind::Failed {
                            message: "The host returned a receipt for a different command. Deletion stopped.".into(),
                        },
                    );
                    return;
                }
                self.last_action_receipt = Some(receipt.clone());
                if let crate::domain::command::CommandReceipt::Rejected { code, .. } = &receipt {
                    if self.settle_delete_flow_outcome(
                        &action,
                        DeleteFlowSettleKind::Rejected {
                            message: format!("host rejected command: {code:?}"),
                        },
                    ) {
                        return;
                    }
                    let retained = self.retain_pending_host_action(action.clone());
                    self.set_execution_failure(
                        &action,
                        format!("host rejected command: {code:?}"),
                        false,
                    );
                    if !retained {
                        self.set_action_capacity_failure(action.id);
                    }
                    return;
                }
                if self.settle_delete_flow_outcome(&action, DeleteFlowSettleKind::Accepted) {
                    // Continue through ordinary receipt bookkeeping below so the
                    // action leaves pending lanes, but skip generic composer paths.
                }
                if let Some(command_id) = command_id {
                    self.pending_host_actions
                        .retain(|action| native_command_id(&action.command) != Some(command_id));
                    if self
                        .retained_action_overflow
                        .as_ref()
                        .is_some_and(|action| {
                            native_command_id(&action.command) == Some(command_id)
                        })
                    {
                        self.retained_action_overflow = None;
                    }
                }
                if self.last_action_failure.as_ref().is_some_and(|failure| {
                    failure.action_id() == action_id && failure.command_id() == command_id
                }) {
                    self.last_action_failure = None;
                    self.restore_connected_host_state();
                }
                let settled_active_composer = if let (Some(composer), Some(command_id)) =
                    (self.composer.as_mut(), command_id)
                {
                    composer
                        .pending_intent()
                        .is_some_and(|pending| pending.command_id == command_id)
                        && composer.settle_pending(command_id).is_ok()
                } else {
                    false
                };
                if settled_active_composer {
                    self.cache_current_composer_draft();
                }
                if let Some(command_id) = command_id {
                    if let Some(submission) = self.pending_composer_submissions.remove(&command_id)
                    {
                        if let Some(seed) = submission.automatic_title_seed.as_deref() {
                            if let Some(snapshot) = self
                                .client_model
                                .as_ref()
                                .and_then(|model| model.task(submission.key.task_id))
                            {
                                if let Some(proposed_title) =
                                    automatic_task_title(&snapshot.task.title, seed)
                                {
                                    self.pending_automatic_titles.insert(
                                        submission.key.task_id,
                                        PendingAutomaticTitle {
                                            expected_title: snapshot.task.title.clone(),
                                            proposed_title,
                                            due: Instant::now() + AUTOMATIC_TASK_TITLE_DELAY,
                                        },
                                    );
                                }
                            }
                        }
                        let open_provider_terminal = submission.open_provider_terminal;
                        let active_matches = self.composer.as_ref().is_some_and(|composer| {
                            let fence = composer.fence();
                            submission.key
                                == ComposerDraftKey::new(fence.task_id, fence.agent_session_id)
                        });
                        if active_matches && !settled_active_composer {
                            let cleared = self.composer.as_mut().is_some_and(|composer| {
                                composer
                                    .clear_draft_if_matches(&submission.draft)
                                    .unwrap_or(false)
                            });
                            if cleared {
                                self.cache_current_composer_draft();
                            }
                        } else if self.composer_drafts.get(&submission.key)
                            == Some(&submission.draft)
                        {
                            self.composer_drafts.remove(&submission.key);
                            self.composer_drafts_dirty = true;
                        }
                        // The provider prompt contains workspace-relative image
                        // references. Detach them from this composer after the
                        // accepted send, but leave the staged files for the
                        // provider to read; bounded TTL cleanup owns deletion.
                        self.detach_composer_images_for_key(submission.key, &submission.image_ids);
                        if open_provider_terminal {
                            self.set_provider_terminal_visible(true);
                        }
                    }
                }
                self.composer_error = None;
                if let NativeHostCommand::TaskCreateV2 { arguments, .. } = &action.command {
                    self.pending_select_task = Some(arguments.task_id);
                    if self.task_list.task_ids().contains(&arguments.task_id) {
                        let _ = self.select_projected_task(arguments.task_id);
                    }
                }
            }
            NativeHostActionOutcome::Queried {
                action,
                detail,
                body,
            } => {
                let action_id = action.id;
                let request_id = native_request_id(&action.command);
                self.last_query_detail = Some(detail);
                self.apply_query_body(&action, body);
                if let Some(request_id) = request_id {
                    self.pending_host_actions
                        .retain(|pending| native_request_id(&pending.command) != Some(request_id));
                    if self
                        .retained_action_overflow
                        .as_ref()
                        .is_some_and(|pending| {
                            native_request_id(&pending.command) == Some(request_id)
                        })
                    {
                        self.retained_action_overflow = None;
                    }
                } else {
                    self.pending_host_actions
                        .retain(|pending| !same_native_action_identity(pending, &action));
                    if self
                        .retained_action_overflow
                        .as_ref()
                        .is_some_and(|pending| same_native_action_identity(pending, &action))
                    {
                        self.retained_action_overflow = None;
                    }
                }
                if self
                    .last_action_failure
                    .as_ref()
                    .is_some_and(|failure| failure.action_id() == action_id)
                {
                    self.last_action_failure = None;
                    self.restore_connected_host_state();
                }
            }
            NativeHostActionOutcome::Failed { action, error } => {
                if is_native_query_command(&action.command) {
                    self.settle_native_query_failure(&action, error);
                    return;
                }
                if self.settle_delete_flow_outcome(
                    &action,
                    DeleteFlowSettleKind::Failed {
                        message: error.clone(),
                    },
                ) {
                    return;
                }
                if action.id == action::ACTION_CONFIG_CREATE_PROJECT {
                    if let Some(draft) = self.add_project.as_mut() {
                        draft.error = Some(error.clone());
                    }
                    let request_id = native_request_id(&action.command);
                    self.pending_host_actions
                        .retain(|pending| native_request_id(&pending.command) != request_id);
                    if self
                        .retained_action_overflow
                        .as_ref()
                        .is_some_and(|pending| native_request_id(&pending.command) == request_id)
                    {
                        self.retained_action_overflow = None;
                    }
                    return;
                }
                self.composer_error = Some(error.clone());
                let retained = self.retain_pending_host_action(action.clone());
                self.set_execution_failure(&action, error, false);
                if !retained {
                    self.set_action_capacity_failure(action.id);
                }
            }
            NativeHostActionOutcome::Uncertain { action, error } => {
                if is_native_query_command(&action.command) {
                    self.settle_native_query_failure(&action, error);
                    return;
                }
                if self.settle_delete_flow_outcome(
                    &action,
                    DeleteFlowSettleKind::Uncertain {
                        message: error.clone(),
                    },
                ) {
                    return;
                }
                let retained = self.retain_pending_host_action(action.clone());
                self.set_execution_failure(&action, error, true);
                if !retained {
                    self.set_action_capacity_failure(action.id);
                }
            }
        }
    }

    fn clear_recovered_action_failure(&mut self) {
        if self.pending_host_actions.is_empty()
            && self.retained_action_overflow.is_none()
            && self.last_action_failure.as_ref().is_some_and(|failure| {
                matches!(
                    failure,
                    NativeHostActionFailure::QueueFull { .. }
                        | NativeHostActionFailure::Disconnected { .. }
                        | NativeHostActionFailure::Stale { .. }
                        | NativeHostActionFailure::ExecutionFailed { .. }
                        | NativeHostActionFailure::ExecutionUncertain { .. }
                )
            })
        {
            self.last_action_failure = None;
            self.restore_connected_host_state();
        }
    }

    fn restore_connected_host_state(&mut self) {
        let Some(runtime_state) = self.host_runtime.as_ref().map(|runtime| match runtime {
            NativeHostRuntimeAttachment::Injected(runtime) => runtime.host_state(),
            NativeHostRuntimeAttachment::Client(runtime) => runtime.host_state(),
        }) else {
            self.host_state = NativeHostState::Disconnected;
            return;
        };
        self.host_state = runtime_state;
    }

    fn controller_tick(&mut self, max: usize) -> bool {
        self.controller_ticks = self.controller_ticks.saturating_add(1);
        self.flush_composer_drafts_if_due(false);
        self.flush_layout_if_due(false);
        self.dispatch_due_automatic_title();
        let mut repaint = self.composer_accessibility_focused
            && self.controller_ticks % COMPOSER_CARET_BLINK_TICKS == 0;
        if let Some(preferences) = self.pending_preferences.pop_back() {
            self.pending_preferences.clear();
            self.preferences = preferences;
            self.terminal.set_preferences(preferences);
            repaint = true;
        }

        // Poll background connect/attach before draining projections so a late
        // runtime is owned by exactly one shell attachment.
        if self.poll_pending_host_bootstrap() {
            repaint = true;
        }
        if should_schedule_host_bootstrap_retry(
            self.retry_host_bootstrap,
            self.host_runtime.is_some(),
            self.pending_bootstrap.is_some(),
            matches!(
                self.host_state,
                NativeHostState::Disconnected | NativeHostState::Error { .. }
            ),
            self.controller_ticks,
        ) {
            match spawn_pending_host_bootstrap(self.profile.clone(), ProcessNativeHostBootstrap) {
                Ok(pending) => {
                    self.pending_bootstrap = Some(pending);
                    self.host_state = NativeHostState::Connecting;
                }
                Err(error) => {
                    self.host_state = NativeHostState::Error {
                        message: bounded_host_error(error.to_string()),
                    };
                }
            }
            repaint = true;
        }

        let runtime_epochs = self
            .host_runtime
            .as_ref()
            .map(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => runtime.epochs(),
                NativeHostRuntimeAttachment::Client(runtime) => runtime.epochs(),
            })
            .unwrap_or_default();
        if self.interaction.sync_host_epochs(runtime_epochs) {
            self.clear_cockpit_projection();
            repaint = true;
        }
        let mut current_epochs = self.interaction.host_runtime_epochs();
        let mut current_navigation_epoch = self.interaction.action_epochs().navigation_epoch;
        self.rebind_pending_host_actions(current_epochs, current_navigation_epoch);

        // Observe new projections before any caller-requested reconciliation.
        // Failed and uncertain actions remain visible until an explicit
        // reconciliation boundary instead of being hidden by a same-tick
        // loopback.
        let mut projections = match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                runtime.drain_projection_messages(max)
            }
            Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                runtime.take_ready_projection_messages(max)
            }
            None => Vec::new(),
        };
        if let Some(outcome) = self
            .host_runtime
            .as_mut()
            .and_then(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
                NativeHostRuntimeAttachment::Client(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
            })
        {
            projections.push(NativeHostProjection {
                kind: NativeHostProjectionKind::Error,
                client_model: None,
                task_preview: None,
                error: Some(
                    "native host action outcome retained under projection pressure".to_string(),
                ),
                epochs: Some(current_epochs),
                action_outcome: Some(outcome),
            });
        }
        let had_projections = !projections.is_empty();
        let mut accepted_projection_kinds = Vec::with_capacity(projections.len());
        for projection in projections {
            let stale_projection = projection.epochs.is_some_and(|epochs| {
                if !epochs.is_strictly_older_than(current_epochs) {
                    self.interaction.sync_host_epochs(epochs);
                    current_epochs = self.interaction.host_runtime_epochs();
                    current_navigation_epoch = self.interaction.action_epochs().navigation_epoch;
                    self.rebind_pending_host_actions(current_epochs, current_navigation_epoch);
                    false
                } else {
                    true
                }
            });
            if stale_projection && projection.action_outcome.is_none() {
                continue;
            }
            accepted_projection_kinds.push(projection.kind);
            if !stale_projection {
                if let Err(error) = self.apply_validated_host_projection_payloads(&projection) {
                    self.host_state = NativeHostState::Error { message: error };
                }
            }
            if let Some(outcome) = projection.action_outcome {
                self.apply_epoch_fenced_action_outcome(outcome);
            } else if let Some(error) = projection.error {
                self.host_state = NativeHostState::Error { message: error };
            }
        }
        if had_projections {
            self.last_projection_kinds = accepted_projection_kinds;
            repaint = true;
        }
        repaint |= self.admit_ready_stream_frames(max);
        repaint |= self.sync_top_bar_from_updater();

        // Keep the primary conversation live without refreshing inactive dock
        // tools. Interactive panes poll faster; background panes stay on the
        // slower cadence. The host page is bounded and replaces the previous
        // retained window, so polling cannot grow client memory.
        let due_priorities = conversation_poll_priorities_due(self.controller_ticks as u64);
        if !due_priorities.is_empty() && self.action_lane_len() < MAX_ACTION_LANE_RECORDS / 2 {
            let max_background = if due_priorities.contains(&ConversationQueryPriority::Background)
            {
                2
            } else {
                0
            };
            let schedule = match self.layout.task_workspace.as_ref() {
                Some(workspace) => self
                    .task_surfaces
                    .conversation_query_schedule(workspace, max_background),
                None => Vec::new(),
            };
            for plan in schedule {
                if !due_priorities.contains(&plan.priority) {
                    continue;
                }
                if self.action_lane_len() >= MAX_ACTION_LANE_RECORDS / 2 {
                    break;
                }
                let after_sequence = self.conversation_after_sequence_for(plan.task_id);
                let record = match plan.priority {
                    ConversationQueryPriority::Interactive => self
                        .interaction
                        .action_on_current_handler(ActionRequest::TaskCockpit {
                            task_id: plan.task_id,
                            query: TaskCockpitQuery::Conversation { after_sequence },
                        }),
                    ConversationQueryPriority::Background => self
                        .interaction
                        .background_conversation_on_current_handler(plan.task_id, after_sequence),
                };
                if let Some(record) = record {
                    let _ = self.enqueue_host_action(record);
                }
            }
            if due_priorities.contains(&ConversationQueryPriority::Background) {
                if let Some(task_id) = self.interaction.selected_task() {
                    if self.cockpit.dock().showing_raw_terminal() {
                        if let Some(record) =
                            self.interaction
                                .action_on_current_handler(ActionRequest::TaskCockpit {
                                    task_id,
                                    query: TaskCockpitQuery::Terminal,
                                })
                        {
                            let _ = self.enqueue_host_action(record);
                        }
                    }
                }
            }
        }

        for _ in 0..max.min(MAX_PENDING_HOST_ACTIONS) {
            let Some(has_pending) = self.host_runtime.as_ref().map(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => runtime.pending_front().is_some(),
                NativeHostRuntimeAttachment::Client(runtime) => runtime.pending_front().is_some(),
            }) else {
                break;
            };
            if !has_pending {
                break;
            }
            repaint = true;

            let pending_action = match self.host_runtime.as_ref() {
                Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                    runtime.pending_front().cloned()
                }
                Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                    runtime.pending_front().cloned()
                }
                None => None,
            };
            if let Some(action) = pending_action.as_ref() {
                if !self.interaction.accepts_action_record(action) {
                    let stale = match self.host_runtime.as_mut() {
                        Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                            runtime.take_pending_front()
                        }
                        Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                            runtime.take_pending_front()
                        }
                        None => None,
                    };
                    if let Some(stale) = stale {
                        if is_native_query_command(&stale.command) {
                            self.discard_native_query_action(&stale);
                            continue;
                        } else if self.retain_pending_host_action(stale.clone()) {
                            self.set_transport_failure(&stale, NativeHostActionResult::Stale);
                        } else {
                            self.set_action_capacity_failure(stale.id);
                        }
                    }
                    break;
                }
            }
            let result = match self.host_runtime.as_mut() {
                Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                    runtime.dispatch_next_pending()
                }
                Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                    runtime.dispatch_next_pending()
                }
                None => break,
            };
            match result {
                NativeHostActionResult::Queued => {
                    self.clear_recovered_action_failure();
                }
                NativeHostActionResult::Disconnected => {
                    if let Some(action) = pending_action.as_ref() {
                        if is_native_query_command(&action.command) {
                            let _ = match self.host_runtime.as_mut() {
                                Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                None => None,
                            };
                            self.settle_native_query_admission_failure(
                                action,
                                NativeHostActionResult::Disconnected,
                            );
                            continue;
                        }
                        self.set_transport_failure(action, NativeHostActionResult::Disconnected);
                    } else {
                        self.host_state = NativeHostState::Disconnected;
                    }
                    break;
                }
                NativeHostActionResult::QueueFull => {
                    if let Some(action) = pending_action.as_ref() {
                        if is_native_query_command(&action.command) {
                            let _ = match self.host_runtime.as_mut() {
                                Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                None => None,
                            };
                            self.settle_native_query_admission_failure(
                                action,
                                NativeHostActionResult::QueueFull,
                            );
                            continue;
                        }
                        self.set_transport_failure(action, NativeHostActionResult::QueueFull);
                    } else {
                        self.host_state = NativeHostState::Error {
                            message: bounded_host_error(
                                "native host worker queue is saturated; action retained"
                                    .to_string(),
                            ),
                        };
                    }
                    break;
                }
                NativeHostActionResult::Stale => {
                    if let Some(action) = pending_action.as_ref() {
                        if is_native_query_command(&action.command) {
                            let _ = match self.host_runtime.as_mut() {
                                Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                                    runtime.take_pending_front()
                                }
                                None => None,
                            };
                            self.settle_native_query_admission_failure(
                                action,
                                NativeHostActionResult::Stale,
                            );
                            continue;
                        }
                        self.set_transport_failure(action, NativeHostActionResult::Stale);
                    }
                    break;
                }
            }
        }

        // AccessKit invokes its OS action handler from the platform thread.
        // The handler only queues bounded requests; this controller tick is
        // the sole GPUI/input owner that resolves them against the current
        // rendered tree and focus capture.
        for queued in self.platform_accessibility.take_actions(max) {
            if !self
                .platform_accessibility
                .is_current_generation(queued.tree_generation)
            {
                // Node ids are only meaningful within the tree generation
                // that produced them.  A reorder/removal must never route an
                // old assistive-technology action to a new row.
                continue;
            }
            let request = queued.request;
            if !matches!(
                request.action,
                accesskit::Action::Click | accesskit::Action::Focus | accesskit::Action::SetValue
            ) {
                continue;
            }
            if matches!(
                request.action,
                accesskit::Action::Click | accesskit::Action::Focus
            ) {
                if let Some(task_id) = self
                    .accessibility_tree
                    .task_for_platform_node(request.target_node)
                {
                    let _ =
                        self.apply_workspace_selection(task_id, WorkspaceSelectionGesture::Plain);
                    repaint = true;
                    continue;
                }
            }
            if matches!(request.action, accesskit::Action::Click) {
                if let Some(action) = self
                    .accessibility_tree
                    .project_action_for_platform_node(request.target_node)
                {
                    match action {
                        ProjectAccessibilityAction::Toggle(project_id) => {
                            self.toggle_project(project_id);
                            self.refresh_accessibility_tree();
                        }
                        ProjectAccessibilityAction::StartAgent(project_id, _) => {
                            self.begin_new_task_for_project(project_id);
                        }
                    }
                    repaint = true;
                    continue;
                }
            }
            let Some(element_id) = self
                .accessibility_tree
                .node_for_platform_id(request.target_node)
                .map(|node| node.element_id().to_string())
            else {
                continue;
            };
            match request.action {
                accesskit::Action::Click => {
                    self.dispatch_named_accessibility_action(&element_id);
                    repaint = true;
                }
                accesskit::Action::Focus if element_id == "native-task-composer-input" => {
                    self.request_composer_accessibility_focus();
                    repaint = true;
                }
                accesskit::Action::Focus if element_id == "native-browser-address" => {
                    self.browser_address_focused = true;
                    self.browser_address_select_all = true;
                    repaint = true;
                }
                accesskit::Action::Focus if element_id == "native-task-search-input" => {
                    self.pending_task_search_focus = true;
                    repaint = true;
                }
                accesskit::Action::Focus if element_id == "native-rename-task-name" => {
                    if let Some(draft) = self.rename_task.as_mut() {
                        draft.title.focus();
                    }
                    self.pending_root_overlay_focus = true;
                    repaint = true;
                }
                accesskit::Action::Focus if element_id == "native-add-project-name" => {
                    if let Some(draft) = self.add_project.as_mut() {
                        draft.name.focus();
                    }
                    self.pending_root_overlay_focus = true;
                    repaint = true;
                }
                accesskit::Action::SetValue if element_id == "native-task-composer-input" => {
                    if let Some(accesskit::ActionData::Value(value)) = request.data {
                        self.replace_composer_accessibility_value(&value);
                        repaint = true;
                    }
                }
                accesskit::Action::SetValue if element_id == "native-browser-address" => {
                    if let Some(accesskit::ActionData::Value(value)) = request.data {
                        self.browser_address_draft = value.to_string();
                        self.browser_address_select_all = false;
                        repaint = true;
                    }
                }
                accesskit::Action::SetValue if element_id == "native-task-search-input" => {
                    if let Some(accesskit::ActionData::Value(value)) = request.data {
                        self.task_search.set_query(value);
                        self.pending_task_search_focus = true;
                        self.refresh_accessibility_tree();
                        repaint = true;
                    }
                }
                accesskit::Action::SetValue if element_id == "native-rename-task-name" => {
                    if let Some(accesskit::ActionData::Value(value)) = request.data {
                        if let Some(draft) = self.rename_task.as_mut() {
                            let _ = draft.title.focus();
                            let _ = draft.title.set_value(value.to_string());
                        }
                        self.refresh_accessibility_tree();
                        repaint = true;
                    }
                }
                accesskit::Action::SetValue if element_id == "native-add-project-name" => {
                    if let Some(accesskit::ActionData::Value(value)) = request.data {
                        if let Some(draft) = self.add_project.as_mut() {
                            let _ = draft.name.focus();
                            let _ = draft.name.set_value(value.to_string());
                        }
                        self.refresh_accessibility_tree();
                        repaint = true;
                    }
                }
                _ => {}
            }
        }

        let offset = self.task_scroll_handle.0.borrow().base_handle.offset().y / px(1.0);
        let metrics = self.theme_tokens().density.physical();
        let first_visible = (offset.max(0.0) / metrics.row_height as f32).floor() as usize;
        let _ = self
            .task_list
            .set_viewport(first_visible, DEFAULT_VISIBLE_ROWS);
        self.offer_first_task_if_needed();
        self.refresh_accessibility_tree();
        repaint
    }

    fn dispatch_due_automatic_title(&mut self) {
        let now = Instant::now();
        let Some((task_id, expected_title, proposed_title)) = self
            .pending_automatic_titles
            .iter()
            .find(|(_, pending)| now >= pending.due)
            .map(|(task_id, pending)| {
                (
                    *task_id,
                    pending.expected_title.clone(),
                    pending.proposed_title.clone(),
                )
            })
        else {
            return;
        };
        let Some(snapshot) = self
            .client_model
            .as_ref()
            .and_then(|model| model.task(task_id))
        else {
            return;
        };
        if snapshot.task.title != expected_title {
            self.pending_automatic_titles.remove(&task_id);
            return;
        }
        self.pending_automatic_titles.remove(&task_id);
        let _ = self.dispatch_action(ActionRequest::TaskRename(
            crate::client::action::TaskRenameArguments {
                task_id,
                title: proposed_title,
            },
        ));
    }

    pub(crate) fn install_window_observers(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.platform_accessibility.attach_window(window);
        let appearance = cx.observe_window_appearance(window, |shell, window, _cx| {
            shell.queue_preferences(RuntimePreferencesSnapshot::from_system(
                window.appearance(),
                window.scale_factor(),
                shell.preferences.density(),
            ));
        });
        let bounds = cx.observe_window_bounds(window, |shell, window, _cx| {
            shell.queue_preferences(RuntimePreferencesSnapshot::from_system(
                window.appearance(),
                window.scale_factor(),
                shell.preferences.density(),
            ));
            shell.record_window_frame(window);
            shell.capture_browser_parent_hwnd(window);
            shell.pump_pending_browser_commands(window);
            shell.reconcile_browser_dock_lifecycle(Some(window));
        });
        self.appearance_subscription = Some(appearance);
        self.bounds_subscription = Some(bounds);
    }

    /// Explicit acknowledged detach path used by UI action and ordinary close.
    pub fn request_acknowledged_client_detach(&mut self) -> Result<(), NativeShellError> {
        let deadline = NativeShutdownDeadline::from_now(NATIVE_SHUTDOWN_BUDGET);
        match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                runtime.acknowledge_client_detach(deadline)?;
                Ok(())
            }
            Some(NativeHostRuntimeAttachment::Injected(_)) => Err(NativeShellError::HostConnect {
                message: "injected host runtime cannot acknowledge detach".to_string(),
            }),
            None => Err(NativeShellError::HostConnect {
                message: "no host runtime attached for client detach".to_string(),
            }),
        }
    }

    /// Explicit full-quit path using inspect_host_quit then confirm_host_quit.
    pub fn request_full_host_quit(
        &mut self,
        allow_uninspected_worktrees: bool,
    ) -> Result<crate::domain::command::CommandReceipt, NativeShellError> {
        let deadline = NativeShutdownDeadline::from_now(NATIVE_SHUTDOWN_BUDGET);
        match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                runtime.confirm_full_host_quit(allow_uninspected_worktrees, deadline)
            }
            Some(NativeHostRuntimeAttachment::Injected(_)) => Err(NativeShellError::HostConnect {
                message: "injected host runtime cannot confirm full quit".to_string(),
            }),
            None => Err(NativeShellError::HostConnect {
                message: "no host runtime attached for full quit".to_string(),
            }),
        }
    }

    pub(crate) fn host_runtime(&self) -> Option<&NativeHostClientRuntime> {
        self.host_runtime
            .as_ref()
            .and_then(|attachment| match attachment {
                NativeHostRuntimeAttachment::Client(runtime) => Some(runtime),
                NativeHostRuntimeAttachment::Injected(_) => None,
            })
    }

    pub(crate) fn host_runtime_mut(&mut self) -> Option<&mut NativeHostClientRuntime> {
        self.host_runtime
            .as_mut()
            .and_then(|attachment| match attachment {
                NativeHostRuntimeAttachment::Client(runtime) => Some(runtime),
                NativeHostRuntimeAttachment::Injected(_) => None,
            })
    }

    fn apply_drained_projection_messages(
        &mut self,
        projections: Vec<NativeHostProjection>,
    ) -> Vec<NativeHostProjectionKind> {
        let runtime_epochs = self
            .host_runtime
            .as_ref()
            .map(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => runtime.epochs(),
                NativeHostRuntimeAttachment::Client(runtime) => runtime.epochs(),
            })
            .unwrap_or_default();
        if self.interaction.sync_host_epochs(runtime_epochs) {
            self.clear_cockpit_projection();
        }
        let mut current_epochs = self.interaction.host_runtime_epochs();
        let mut current_navigation_epoch = self.interaction.action_epochs().navigation_epoch;
        self.rebind_pending_host_actions(current_epochs, current_navigation_epoch);
        let mut kinds = Vec::with_capacity(projections.len());
        for projection in projections {
            let stale_projection = projection.epochs.is_some_and(|epochs| {
                if !epochs.is_strictly_older_than(current_epochs) {
                    self.interaction.sync_host_epochs(epochs);
                    current_epochs = self.interaction.host_runtime_epochs();
                    current_navigation_epoch = self.interaction.action_epochs().navigation_epoch;
                    self.rebind_pending_host_actions(current_epochs, current_navigation_epoch);
                    false
                } else {
                    true
                }
            });
            if stale_projection && projection.action_outcome.is_none() {
                continue;
            }
            kinds.push(projection.kind);
            if !stale_projection {
                if let Err(error) = self.apply_validated_host_projection_payloads(&projection) {
                    self.host_state = NativeHostState::Error { message: error };
                }
            }
            if let Some(outcome) = projection.action_outcome {
                self.apply_epoch_fenced_action_outcome(outcome);
            } else if let Some(error) = projection.error {
                self.host_state = NativeHostState::Error { message: error };
            }
        }
        kinds
    }

    /// Drain only the injected/controller-owned projection queue. The method
    /// is deliberately explicit so GPUI paint/input callbacks cannot perform
    /// transport work. Full projection messages are applied before returning
    /// their kinds so action receipts/outcomes are never discarded.
    pub fn drain_host_projections(&mut self, max: usize) -> Vec<NativeHostProjectionKind> {
        let mut projections = match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                runtime.drain_projection_messages(max)
            }
            Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                runtime.take_ready_projection_messages(max)
            }
            None => Vec::new(),
        };
        if let Some(outcome) = self
            .host_runtime
            .as_mut()
            .and_then(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
                NativeHostRuntimeAttachment::Client(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
            })
        {
            projections.push(NativeHostProjection {
                kind: NativeHostProjectionKind::Error,
                client_model: None,
                task_preview: None,
                error: Some(
                    "native host action outcome retained under projection pressure".to_string(),
                ),
                epochs: None,
                action_outcome: Some(outcome),
            });
        }
        self.apply_drained_projection_messages(projections)
    }

    /// Controller-lane async drain for the single real client. This is kept
    /// separate from synchronous paint/input APIs so a GPUI callback cannot
    /// accidentally await transport work.
    pub async fn drain_host_projections_async(
        &mut self,
        max: usize,
    ) -> Result<Vec<NativeHostProjectionKind>, IpcError> {
        let mut projections = match self.host_runtime.as_mut() {
            Some(NativeHostRuntimeAttachment::Client(runtime)) => {
                runtime.take_ready_projection_messages(max)
            }
            Some(NativeHostRuntimeAttachment::Injected(runtime)) => {
                runtime.drain_projection_messages(max)
            }
            None => Vec::new(),
        };
        if let Some(outcome) = self
            .host_runtime
            .as_mut()
            .and_then(|runtime| match runtime {
                NativeHostRuntimeAttachment::Injected(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
                NativeHostRuntimeAttachment::Client(runtime) => {
                    runtime.take_deferred_action_outcome()
                }
            })
        {
            projections.push(NativeHostProjection {
                kind: NativeHostProjectionKind::Error,
                client_model: None,
                task_preview: None,
                error: Some(
                    "native host action outcome retained under projection pressure".to_string(),
                ),
                epochs: None,
                action_outcome: Some(outcome),
            });
        }
        Ok(self.apply_drained_projection_messages(projections))
    }

    /// Attach exactly one pre-connected host runtime. The shell never opens
    /// another connection when an attachment is present.
    pub(crate) fn attach_host_runtime(
        &mut self,
        host_runtime: NativeHostClientRuntime,
    ) -> Result<(), NativeHostClientRuntime> {
        self.attach_host_runtime_attachment(NativeHostRuntimeAttachment::Client(host_runtime))
            .map_err(|attachment| match attachment {
                NativeHostRuntimeAttachment::Client(runtime) => runtime,
                NativeHostRuntimeAttachment::Injected(_) => {
                    unreachable!("client attach cannot return injected attachment")
                }
            })
    }

    fn attach_host_runtime_attachment(
        &mut self,
        attachment: NativeHostRuntimeAttachment,
    ) -> Result<(), NativeHostRuntimeAttachment> {
        if self.host_runtime.is_some() {
            return Err(attachment);
        }
        match &attachment {
            NativeHostRuntimeAttachment::Client(runtime) => {
                if let Err(error) = runtime.validate_attachment(&self.profile) {
                    self.host_state = NativeHostState::Error {
                        message: bounded_host_error(error.to_string()),
                    };
                    return Err(attachment);
                }
                self.interaction.sync_host_epochs(runtime.epochs());
            }
            NativeHostRuntimeAttachment::Injected(runtime) => {
                self.interaction.sync_host_epochs(runtime.epochs());
            }
        }
        let host_state = match &attachment {
            NativeHostRuntimeAttachment::Client(runtime) => NativeHostState::Connected {
                endpoint: runtime.endpoint().to_string(),
            },
            NativeHostRuntimeAttachment::Injected(runtime) => runtime.host_state(),
        };
        self.host_runtime = Some(attachment);
        self.host_state = host_state;
        Ok(())
    }

    fn poll_pending_host_bootstrap(&mut self) -> bool {
        let Some(pending) = self.pending_bootstrap.as_mut() else {
            return false;
        };
        let Some(result_rx) = pending.result_rx.as_mut() else {
            return false;
        };
        let received = match result_rx.try_recv() {
            Ok(result) => Some(result),
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => Some(Err(NativeShellError::HostConnect {
                message: "native host bootstrap worker disconnected".to_string(),
            })),
        };
        let Some(result) = received else {
            return false;
        };
        let mut pending = self
            .pending_bootstrap
            .take()
            .expect("pending bootstrap present after try_recv");
        // Drop the receiver before joining/retaining so a racing send still
        // cleans the runtime on the bootstrap thread. Taking worker prevents
        // Drop from joining twice.
        drop(pending.result_rx.take());
        let worker = pending.worker.take();
        match result {
            Ok(attachment) => {
                if let Err(returned) = self.attach_host_runtime_attachment(attachment) {
                    drop(returned);
                    self.host_state = NativeHostState::Error {
                        message: bounded_host_error(
                            "native host runtime already attached during bootstrap",
                        ),
                    };
                }
            }
            Err(error) => {
                eprintln!("devmanager native host bootstrap failed: {error}");
                self.host_state = NativeHostState::Error {
                    message: bounded_host_error(error.to_string()),
                };
            }
        }
        finish_pending_bootstrap_worker(worker);
        true
    }

