    fn browse_add_project_folder(&mut self, cx: &mut Context<Self>) {
        self.schedule_folder_prompt(cx);
    }

    fn submit_add_project(&mut self, cx: &mut Context<Self>) {
        if self
            .add_project
            .as_ref()
            .is_some_and(|draft| draft.path.trim().is_empty())
        {
            self.schedule_folder_prompt(cx);
            return;
        }
        self.commit_add_project();
    }

    fn commit_add_project(&mut self) {
        let Some(draft) = self.add_project.as_ref() else {
            return;
        };
        if draft.submitting {
            return;
        }
        let name = draft.name.value().trim().to_string();
        let root_path = draft.path.trim().to_string();
        if root_path.is_empty() {
            self.pending_folder_prompt = true;
            return;
        }
        if name.is_empty() {
            if let Some(draft) = self.add_project.as_mut() {
                draft.error = Some("Give this project a name.".into());
            }
            return;
        }
        if self
            .dispatch_action(ActionRequest::TaskCockpit {
                task_id: TaskId::new(),
                query: TaskCockpitQuery::ConfigCreateProject { name, root_path },
            })
            .is_some()
        {
            if let Some(draft) = self.add_project.as_mut() {
                draft.error = Some("Couldn't add this project. Try again.".into());
                draft.submitting = false;
            }
            return;
        }
        if let Some(draft) = self.add_project.as_mut() {
            draft.submitting = true;
            draft.error = None;
        }
    }

    fn finish_add_project_after_host_accept(&mut self) {
        self.add_project = None;
        self.offer_first_task_if_needed();
    }

    fn offer_first_task_if_needed(&mut self) {}

    fn start_task_with_agent(&mut self, kind: ProviderKind) {
        let Some(project_id) = self.current_workspace_project_id() else {
            return;
        };
        self.start_task_with_agent_for_project(project_id, kind);
    }

    fn start_task_with_agent_for_project(&mut self, project_id: ProjectId, kind: ProviderKind) {
        let Some(snapshot) = self.agent_connection.as_ref() else {
            return;
        };
        if !inbox_agent_actions(snapshot)
            .iter()
            .any(|action| action.provider == kind)
        {
            return;
        }
        self.selected_project_id = Some(project_id);
        let _ = self.dispatch_action(ActionRequest::TaskCreateV2(
            crate::client::action::TaskCreateV2Arguments {
                task_id: TaskId::new(),
                environment_id: crate::domain::id::EnvironmentId::new(),
                title: placeholder_task_title(kind).to_string(),
                description: None,
                project_id,
                workspace: crate::workspace::WorkspaceRequest::main(),
                primary_provider: Some(kind),
                defer_primary_provider_start: false,
            },
        ));
    }

    fn archive_selected_task(&mut self) {
        let Some(task_id) = self.interaction.selected_task() else {
            return;
        };
        let _ = self.dispatch_action(ActionRequest::TaskArchive { task_id });
    }

    fn settle_selected_task(&mut self) {
        let Some(task_id) = self.interaction.selected_task() else {
            return;
        };
        let _ = self.dispatch_action(ActionRequest::TaskSettle { task_id });
    }

    fn reopen_task(&mut self, task_id: TaskId) {
        let _ = self.select_projected_task(task_id);
        let _ = self.dispatch_action(ActionRequest::TaskReopen { task_id });
    }

    fn begin_task_delete(&mut self, task_id: TaskId) {
        if self
            .client_model
            .as_ref()
            .and_then(|model| model.tasks().get(&task_id))
            .is_none()
        {
            return;
        }
        // Opening a new confirmation permanently disarms any prior deferred delete.
        self.cancel_delete_task_flow();
        self.interaction.sync_selected_task(Some(task_id));
        self.delete_task = Some(DeleteTaskDraft {
            task_id,
            title: self.task_row_title(task_id),
            error: None,
            stage: DeleteTaskStage::Confirming,
        });
        self.new_task = None;
        self.rename_task = None;
        self.interaction.close_palettes();
    }

    fn confirm_task_delete(&mut self) {
        let Some(draft) = self.delete_task.as_ref() else {
            return;
        };
        // Duplicate Enter/click while archive or delete is already queued must
        // not enqueue another host command.
        if draft.stage.is_submitting() {
            return;
        }
        if self.retired_delete_flow_commands.len() >= MAX_ACTION_LANE_RECORDS {
            if let Some(draft) = self.delete_task.as_mut() {
                draft.error = Some("Too many deletion requests are awaiting a result. Reconnect before trying again.".into());
            }
            return;
        }
        let draft = self.delete_task.as_ref().expect("confirmed draft");
        let task_id = draft.task_id;
        let archived = self
            .client_model
            .as_ref()
            .and_then(|model| model.tasks().get(&task_id))
            .is_some_and(|snapshot| {
                snapshot.task.lifecycle == crate::domain::task::TaskLifecycle::Archived
            });
        if !archived {
            match self.dispatch_action_recorded(ActionRequest::TaskArchive { task_id }) {
                Ok(record) => {
                    let Some(command_id) = native_command_id(&record.command) else {
                        if let Some(draft) = self.delete_task.as_mut() {
                            draft.error = Some("Couldn't archive the task before deleting.".into());
                            draft.stage = DeleteTaskStage::Confirming;
                        }
                        return;
                    };
                    if let Some(draft) = self.delete_task.as_mut() {
                        draft.error = None;
                        draft.stage = DeleteTaskStage::AwaitingArchive {
                            command_id,
                            archive_accepted: false,
                        };
                    }
                }
                Err(failure) => self.settle_delete_admission_failure(failure),
            }
            return;
        }
        self.queue_confirmed_task_delete(task_id);
    }

    fn queue_confirmed_task_delete(&mut self, task_id: TaskId) {
        let Some(draft) = self.delete_task.as_ref() else {
            return;
        };
        if draft.task_id != task_id || draft.stage.is_submitting() {
            return;
        }
        match self.dispatch_action_recorded(ActionRequest::TaskDelete { task_id }) {
            Ok(record) => {
                let Some(command_id) = native_command_id(&record.command) else {
                    if let Some(draft) = self.delete_task.as_mut() {
                        draft.error = Some("Couldn't delete the task. Try again.".into());
                        draft.stage = DeleteTaskStage::Confirming;
                    }
                    return;
                };
                if let Some(draft) = self.delete_task.as_mut() {
                    draft.error = None;
                    draft.stage = DeleteTaskStage::AwaitingDelete { command_id };
                }
            }
            Err(failure) => self.settle_delete_admission_failure(failure),
        }
    }

    /// Advance only when the still-live confirmation draft matches, the exact
    /// archive command has been Accepted, and the projected task is Archived.
    /// Never recreates a cancelled or replaced draft.
    fn try_advance_pending_delete_after_archive(&mut self) {
        let Some(draft) = self.delete_task.as_ref() else {
            return;
        };
        let DeleteTaskStage::AwaitingArchive {
            archive_accepted: true,
            ..
        } = draft.stage
        else {
            return;
        };
        let task_id = draft.task_id;
        let archived = self
            .client_model
            .as_ref()
            .and_then(|model| model.tasks().get(&task_id))
            .is_some_and(|snapshot| {
                snapshot.task.lifecycle == crate::domain::task::TaskLifecycle::Archived
            });
        if !archived {
            return;
        }
        match self.dispatch_action_recorded(ActionRequest::TaskDelete { task_id }) {
            Ok(record) => {
                let Some(command_id) = native_command_id(&record.command) else {
                    if let Some(draft) = self.delete_task.as_mut() {
                        draft.error = Some("Couldn't delete the task. Try again.".into());
                        draft.stage = DeleteTaskStage::Confirming;
                    }
                    return;
                };
                if let Some(draft) = self.delete_task.as_mut() {
                    if draft.task_id != task_id {
                        // Draft replaced mid-dispatch; retire the orphaned delete.
                        self.retire_delete_flow_command(command_id);
                        return;
                    }
                    draft.error = None;
                    draft.stage = DeleteTaskStage::AwaitingDelete { command_id };
                } else {
                    self.retire_delete_flow_command(command_id);
                }
            }
            Err(failure) => self.settle_delete_admission_failure(failure),
        }
    }

    fn settle_delete_admission_failure(&mut self, failure: NativeActionDispatchFailure) {
        // A captured command can be retained by enqueue_host_action even when
        // admission fails. It must never survive as an implicit delete retry.
        if let Some(command_id) = failure
            .record
            .as_ref()
            .and_then(|record| native_command_id(&record.command))
        {
            self.discard_host_action_by_command_id(command_id);
        }
        if failure.record.as_ref().is_some_and(|record| {
            self.last_action_failure
                .as_ref()
                .is_some_and(|last| last.command_id().is_none() && last.action_id() == record.id)
        }) {
            self.last_action_failure = None;
            self.restore_connected_host_state();
        }
        if let Some(draft) = self.delete_task.as_mut() {
            draft.error = Some(failure.message);
            draft.stage = DeleteTaskStage::Confirming;
        }
    }

    /// Permanently disarm deferred deletion. An already-sent archive may still
    /// complete on the host, but no Delete follows after cancellation.
    fn cancel_delete_task_flow(&mut self) {
        if let Some(draft) = self.delete_task.take() {
            match draft.stage {
                DeleteTaskStage::AwaitingArchive {
                    command_id,
                    archive_accepted: true,
                } => {
                    self.discard_host_action_by_command_id(command_id);
                }
                DeleteTaskStage::AwaitingArchive { command_id, .. }
                | DeleteTaskStage::AwaitingDelete { command_id } => {
                    self.retire_delete_flow_command(command_id);
                }
                DeleteTaskStage::Confirming => {}
            }
        }
    }

    fn retire_delete_flow_command(&mut self, command_id: CommandId) {
        self.discard_host_action_by_command_id(command_id);
        if !self.retired_delete_flow_commands.contains(&command_id) {
            // Never evict an unresolved cancellation: a late result must not
            // regain generic retry authority. New confirmations are bounded.
            self.retired_delete_flow_commands.push(command_id);
        }
    }

    fn discard_host_action_by_command_id(&mut self, command_id: CommandId) {
        self.pending_host_actions
            .retain(|pending| native_command_id(&pending.command) != Some(command_id));
        if self
            .retained_action_overflow
            .as_ref()
            .is_some_and(|pending| native_command_id(&pending.command) == Some(command_id))
        {
            self.retained_action_overflow = None;
        }
        if self
            .last_action_failure
            .as_ref()
            .is_some_and(|failure| failure.command_id() == Some(command_id))
        {
            self.last_action_failure = None;
            self.restore_connected_host_state();
        }
    }

    fn delete_flow_command_id(&self) -> Option<CommandId> {
        match self.delete_task.as_ref()?.stage {
            DeleteTaskStage::AwaitingArchive { command_id, .. }
            | DeleteTaskStage::AwaitingDelete { command_id } => Some(command_id),
            DeleteTaskStage::Confirming => None,
        }
    }

    fn matches_live_delete_flow_command(&self, action: &NativeActionRecord) -> bool {
        let Some(expected) = self.delete_flow_command_id() else {
            return false;
        };
        if native_command_id(&action.command) != Some(expected) {
            return false;
        }
        match (
            action.task_id,
            self.delete_task.as_ref().map(|draft| draft.task_id),
        ) {
            (Some(action_task), Some(draft_task)) => action_task == draft_task,
            _ => true,
        }
    }

    fn is_retired_delete_flow_command(&self, action: &NativeActionRecord) -> bool {
        native_command_id(&action.command)
            .is_some_and(|command_id| self.retired_delete_flow_commands.contains(&command_id))
    }

    /// Handle archive/delete outcomes for the live confirmation draft. Returns
    /// true when the outcome belonged to this flow (caller must not retry).
    fn settle_delete_flow_outcome(
        &mut self,
        action: &NativeActionRecord,
        kind: DeleteFlowSettleKind,
    ) -> bool {
        if self.is_retired_delete_flow_command(action) {
            if let Some(command_id) = native_command_id(&action.command) {
                self.discard_host_action_by_command_id(command_id);
                self.retired_delete_flow_commands
                    .retain(|id| *id != command_id);
            }
            // Late outcomes after cancel/failure must not stomp another modal.
            return true;
        }
        if !self.matches_live_delete_flow_command(action) {
            return false;
        }
        let Some(command_id) = native_command_id(&action.command) else {
            return true;
        };
        let uncertain = matches!(
            &kind,
            DeleteFlowSettleKind::Uncertain { .. } | DeleteFlowSettleKind::Stale { .. }
        );
        match kind {
            DeleteFlowSettleKind::Accepted => {
                let mut advance_after_archive = false;
                let mut clear_after_delete = false;
                if let Some(draft) = self.delete_task.as_mut() {
                    match draft.stage {
                        DeleteTaskStage::AwaitingArchive {
                            command_id: expected,
                            ..
                        } if expected == command_id => {
                            draft.stage = DeleteTaskStage::AwaitingArchive {
                                command_id: expected,
                                archive_accepted: true,
                            };
                            draft.error = None;
                            advance_after_archive = true;
                        }
                        DeleteTaskStage::AwaitingDelete {
                            command_id: expected,
                        } if expected == command_id => {
                            clear_after_delete = true;
                        }
                        _ => {}
                    }
                }
                self.discard_host_action_by_command_id(command_id);
                if clear_after_delete {
                    self.delete_task = None;
                    self.interaction.sync_selected_task(None);
                } else if advance_after_archive {
                    self.try_advance_pending_delete_after_archive();
                }
            }
            DeleteFlowSettleKind::Rejected { message }
            | DeleteFlowSettleKind::Failed { message }
            | DeleteFlowSettleKind::Uncertain { message }
            | DeleteFlowSettleKind::Stale { message } => {
                if uncertain {
                    self.retire_delete_flow_command(command_id);
                } else {
                    self.discard_host_action_by_command_id(command_id);
                }
                if let Some(draft) = self.delete_task.as_mut() {
                    draft.error = Some(message);
                    draft.stage = DeleteTaskStage::Confirming;
                }
            }
        }
        true
    }

    fn begin_new_task(&mut self) {
        let project_id = match self.project_scope() {
            ProjectScope::Project(project_id) => Some(project_id),
            ProjectScope::All => self.current_workspace_project_id(),
        };
        let Some(project_id) = project_id else {
            self.open_add_project();
            return;
        };
        self.begin_new_task_for_project(project_id);
    }

    fn begin_new_task_for_project(&mut self, project_id: ProjectId) {
        self.selected_project_id = Some(project_id);
        self.new_task = Some(NewTaskDraft {
            project_id,
            error: None,
        });
        self.pending_root_overlay_focus = true;
        self.rename_task = None;
        self.cancel_delete_task_flow();
        self.add_project = None;
        self.interaction.close_palettes();
    }

    fn submit_new_task(&mut self) {
        let Some(draft) = self.new_task.as_ref() else {
            return;
        };
        let project_id = draft.project_id;
        let provider_kind = self
            .layout
            .composer_provider
            .unwrap_or(crate::providers::ProviderKind::Codex);
        if self
            .dispatch_action_checked(ActionRequest::TaskCreateV2(
                crate::client::action::TaskCreateV2Arguments {
                    task_id: TaskId::new(),
                    environment_id: crate::domain::id::EnvironmentId::new(),
                    title: "New task".to_string(),
                    description: None,
                    project_id,
                    workspace: crate::workspace::WorkspaceRequest::main(),
                    primary_provider: Some(provider_kind),
                    defer_primary_provider_start: true,
                },
            ))
            .is_err()
        {
            if let Some(draft) = self.new_task.as_mut() {
                draft.error = Some("Couldn't create the task. Try again.".into());
            }
            return;
        }
        self.new_task = None;
    }

    fn begin_task_rename(&mut self, task_id: TaskId) {
        self.interaction.sync_selected_task(Some(task_id));
        let current = self.task_row_title(task_id);
        let mut title = TextField::new("Task name").expect("rename task field");
        let _ = title.set_value(current);
        title.select_all();
        title.focus();
        self.rename_task = Some(RenameTaskDraft {
            task_id,
            title,
            error: None,
        });
        self.pending_root_overlay_focus = true;
        self.new_task = None;
        self.cancel_delete_task_flow();
        self.interaction.close_palettes();
    }

    fn submit_task_rename(&mut self) {
        let Some(draft) = self.rename_task.as_ref() else {
            return;
        };
        let title = draft.title.value().trim().to_string();
        if title.is_empty() {
            if let Some(draft) = self.rename_task.as_mut() {
                draft.error = Some("Give this task a name.".into());
            }
            return;
        }
        let task_id = draft.task_id;
        if self
            .dispatch_action_checked(ActionRequest::TaskRename(
                crate::client::action::TaskRenameArguments { task_id, title },
            ))
            .is_err()
        {
            if let Some(draft) = self.rename_task.as_mut() {
                draft.error = Some("Couldn't rename the task. Try again.".into());
            }
            return;
        }
        self.pending_automatic_titles.remove(&task_id);
        self.rename_task = None;
    }

    fn request_composer_accessibility_focus(&mut self) {
        if self.composer.is_none() {
            return;
        }
        self.pending_composer_focus = true;
        self.composer_accessibility_focused = true;
        if let Err(error) = self.focus_current_composer_input() {
            self.composer_error = Some(error.to_string());
        } else {
            self.composer_error = None;
        }
    }

    fn replace_composer_accessibility_value(&mut self, value: &str) {
        let current_utf16 = self
            .composer
            .as_ref()
            .map(|composer| composer.draft_text().encode_utf16().count())
            .unwrap_or_default();
        match self.replace_composer_platform_text(Some(0..current_utf16), value) {
            Ok(_) => {
                self.composer_error = None;
            }
            Err(error) => {
                self.composer_error = Some(error.to_string());
            }
        }
    }

    fn dispatch_named_accessibility_action(&mut self, element_id: &str) {
        match element_id {
            "native-projects-add" | "native-sidebar-new-project" => {
                self.interaction.close_palettes();
                self.new_task = None;
                if self.shows_add_project_plus() {
                    self.pending_folder_prompt = true;
                } else {
                    self.settings_open = true;
                }
            }
            "native-sidebar-new-task" => {
                self.begin_new_task();
            }
            "native-inbox-plus-claude" => self.start_task_with_agent(ProviderKind::ClaudeCode),
            "native-inbox-plus-codex" => self.start_task_with_agent(ProviderKind::Codex),
            "native-task-settle" => self.settle_selected_task(),
            "native-task-restore" => {
                if let Some(task_id) = self.interaction.selected_task() {
                    self.reopen_task(task_id);
                }
            }
            "native-task-archive" => self.archive_selected_task(),
            "native-task-delete" => {
                if let Some(task_id) = self.interaction.selected_task() {
                    self.begin_task_delete(task_id);
                }
            }
            "native-delete-task-submit" => self.confirm_task_delete(),
            "native-delete-task-cancel" => self.cancel_delete_task_flow(),
            "native-task-composer-input" => self.request_composer_accessibility_focus(),
            "native-composer-model" => self.open_composer_model_selector(),
            "native-composer-reasoning" => self.open_composer_reasoning_selector(),
            "native-composer-access" => self.open_composer_access_selector(),
            "native-sidebar-archived" => {
                self.show_archived_tasks = !self.show_archived_tasks;
                self.refresh_accessibility_tree();
            }
            "native-task-composer-attach" => self.pending_composer_image_prompt = true,
            "native-task-composer-send" => self.activate_composer_control(ComposerControl::SendNow),
            "native-shell-tools-affordance" => self.open_project_action_menu(),
            "native-task-open" => self.begin_header_open(),
            "native-task-commit" => self.begin_header_commit(),
            "native-browser-back" => {
                self.dispatch_browser_chrome_command(BrowserCommand::Back {
                    tab_id: "conversation".into(),
                });
            }
            "native-browser-forward" => {
                self.dispatch_browser_chrome_command(BrowserCommand::Forward {
                    tab_id: "conversation".into(),
                });
            }
            "native-browser-reload" => {
                self.dispatch_browser_chrome_command(BrowserCommand::Reload {
                    tab_id: "conversation".into(),
                });
            }
            "native-browser-address" => {
                self.browser_address_focused = true;
                self.browser_address_select_all = true;
            }
            "native-browser-go" => {
                let url = self.browser_address_draft.trim().to_string();
                if !url.is_empty() {
                    self.dispatch_browser_chrome_command(BrowserCommand::Navigate {
                        tab_id: "conversation".into(),
                        url,
                    });
                }
            }
            "native-shell-context-dock-toggle" => self.toggle_pane(PaneEdge::Dock),
            "native-task-center-conversation" => self.set_provider_terminal_visible(false),
            "native-task-center-terminal" => self.set_provider_terminal_visible(true),
            "native-task-composer-answer" => {
                self.activate_composer_control(ComposerControl::Answer)
            }
            "native-task-composer-approve" => {
                self.activate_composer_approval(ApprovalDecision::Approve)
            }
            "native-task-composer-reject" => {
                self.activate_composer_approval(ApprovalDecision::Reject { reason: None })
            }
            "native-add-project-submit" => {
                if self
                    .add_project
                    .as_ref()
                    .is_some_and(|draft| draft.path.trim().is_empty())
                {
                    self.pending_folder_prompt = true;
                } else {
                    self.commit_add_project();
                }
            }
            "native-add-project-browse" => self.pending_folder_prompt = true,
            "native-add-project-cancel" => self.add_project = None,
            "native-new-task-submit" => self.submit_new_task(),
            "native-new-task-cancel" => self.new_task = None,
            "native-rename-task-submit" => self.submit_task_rename(),
            "native-rename-task-cancel" => self.rename_task = None,
            "native-header-settings" => self.settings_open = true,
            "native-connect-refresh" | "native-settings-refresh" => {
                let _ = self.dispatch_agent_connection_query(false);
            }
            "native-settings-cancel" => self.close_settings(),
            _ => {
                if let Some(selector) = Self::repository_selector_from_element_id(element_id) {
                    self.select_changes_repository(selector);
                } else if let Some((_, _, digit)) = NATIVE_DOCK_TABS
                    .iter()
                    .find(|(_, dock_element_id, _)| *dock_element_id == element_id)
                {
                    self.dispatch_keyboard(KeyboardShortcut::alt(
                        crate::ui::actions::ShortcutKey::Digit(*digit),
                    ));
                }
            }
        }
    }

    fn repository_selector_from_element_id(element_id: &str) -> Option<TaskRepositorySelector> {
        match element_id {
            "native-changes-repo-workspace" => Some(TaskRepositorySelector::Workspace),
            "native-changes-repo-project-root" => Some(TaskRepositorySelector::ProjectRoot),
            other => other
                .strip_prefix("native-changes-repo-folder-")
                .map(|folder_config_id| TaskRepositorySelector::Folder {
                    folder_config_id: folder_config_id.to_owned(),
                }),
        }
    }

    fn agent_presence_for(&self, provider: ConfigSidebarProviderKind) -> AgentPresence {
        self.agent_connection
            .as_ref()
            .and_then(|snapshot| {
                snapshot
                    .agents
                    .iter()
                    .find(|row| row.provider == provider)
                    .map(|row| row.presence)
            })
            .unwrap_or(AgentPresence::Checking)
    }

    fn run_palette_item(&mut self, item: PaletteItem, cx: &mut Context<Self>) {
        self.interaction.close_palettes();
        match item {
            PaletteItem::AddProject => self.begin_choose_folder(cx),
            PaletteItem::ToggleSidebar => self.toggle_pane(PaneEdge::Sidebar),
            PaletteItem::ToggleDock => self.toggle_pane(PaneEdge::Dock),
            PaletteItem::ToggleTaskCanvas => {
                self.set_provider_terminal_visible(!self.cockpit.dock().showing_raw_terminal())
            }
            PaletteItem::ResetLayout => self.reset_layout(),
        }
    }

    pub fn task_list(&self) -> &TaskList {
        &self.task_list
    }

    pub fn inbox(&self) -> &Inbox {
        &self.inbox
    }

    pub fn rendered_task_count(&self) -> usize {
        self.task_list
            .rendered_task_ids()
            .len()
            .min(MAX_RENDERED_TASK_ROWS)
    }

    /// Semantic status color for the current host connection.
    fn host_tone(&self, tokens: crate::ui::tokens::ThemeTokens) -> crate::ui::tokens::Color {
        match &self.host_state {
            NativeHostState::Connected { .. } => tokens.status.success,
            NativeHostState::Connecting => tokens.status.warning,
            NativeHostState::Disconnected => tokens.status.inactive,
            NativeHostState::Error { .. } => tokens.status.destructive,
        }
    }

    /// Title without the status suffix. `task_row_label` keeps the suffix
    /// because the accessibility tree reads a row as a single string.
    fn task_row_title(&self, task_id: TaskId) -> String {
        if let Some(row) = self.inbox.row(task_id) {
            return row.title.clone();
        }
        self.client_model
            .as_ref()
            .and_then(|model| model.tasks().get(&task_id))
            .map(|snapshot| snapshot.task.title.clone())
            .unwrap_or_else(|| format!("Task {task_id}"))
    }

    fn task_row_status(&self, task_id: TaskId) -> Option<VisibleTaskStatus> {
        let projected = self.inbox.row(task_id).map(|row| row.status).or_else(|| {
            self.client_model
                .as_ref()?
                .tasks()
                .get(&task_id)
                .map(|snapshot| snapshot.visible_status())
        })?;
        if matches!(
            projected,
            VisibleTaskStatus::Working | VisibleTaskStatus::Settling
        ) && self.task_surfaces.conversation_turn_completed(task_id)
        {
            Some(VisibleTaskStatus::Idle)
        } else {
            Some(projected)
        }
    }

    /// Second row line, built only from facts the row projection already
    /// carries so the list reads without opening the task.
    fn task_row_detail(&self, task_id: TaskId) -> String {
        let status = self
            .task_row_status(task_id)
            .map(visible_status_label)
            .unwrap_or("Unprojected");
        let Some(row) = self.inbox.row(task_id) else {
            return status.to_string();
        };
        let mut parts = vec![status.to_string()];
        if !row.display.project.trim().is_empty() {
            parts.push(row.display.project.clone());
        }
        if !row.display.worktree.trim().is_empty() {
            parts.push(row.display.worktree.clone());
        }
        if row.unread_event_count > 0 {
            parts.push(format!("{} unread", row.unread_event_count));
        }
        parts.join(" · ")
    }

    /// Status colors are always paired with their textual label, so no state
    /// in this shell is carried by color alone.
    fn status_tone(
        status: Option<VisibleTaskStatus>,
        tokens: crate::ui::tokens::ThemeTokens,
    ) -> crate::ui::tokens::Color {
        match status {
            Some(VisibleTaskStatus::Failed) => tokens.status.destructive,
            Some(VisibleTaskStatus::UncertainOutcome) | Some(VisibleTaskStatus::Settling) => {
                tokens.status.warning
            }
            Some(VisibleTaskStatus::NeedsApproval) | Some(VisibleTaskStatus::NeedsAnswer) => {
                tokens.status.attention
            }
            Some(VisibleTaskStatus::Working) => tokens.status.external,
            Some(VisibleTaskStatus::ReadyForReview) => tokens.status.success,
            Some(VisibleTaskStatus::Idle) | Some(VisibleTaskStatus::Disconnected) | None => {
                tokens.status.inactive
            }
        }
    }

    fn tone_dot(color: crate::ui::tokens::Color, diameter: f32) -> AnyElement {
        div()
            .flex_none()
            .w(px(diameter))
            .h(px(diameter))
            .rounded_full()
            .bg(color.to_gpui())
            .into_any_element()
    }

    /// Compact labelled fact. Keeping these as separate chips instead of one
    /// concatenated sentence lets the eye find a single value without reading
    /// the whole line.
    fn meta_chip(
        label: &'static str,
        value: impl Into<String>,
        tokens: crate::ui::tokens::ThemeTokens,
    ) -> AnyElement {
        div()
            .flex()
            .flex_none()
            .items_center()
            .gap(px(tokens.density.spacing.xs))
            .px(px(tokens.density.spacing.sm))
            .py(px(tokens.density.spacing.xxs))
            .rounded(px(tokens.density.radii.pill))
            .bg(tokens.surfaces.raised.to_gpui())
            .text_size(px(tokens.density.typography.caption))
            .line_height(px(tokens.density.typography.caption_line_height))
            .child(div().text_color(tokens.text.muted.to_gpui()).child(label))
            .child(
                div()
                    .font_weight(FontWeight::MEDIUM)
                    .text_color(tokens.text.primary.to_gpui())
                    .child(value.into()),
            )
            .into_any_element()
    }

    /// One labelled fact on its own line. A row of chips reads as debug output
    /// once there are more than a few; a two-column list keeps the labels
    /// scannable and lets the values truncate independently.
    fn meta_row(
        label: &'static str,
        value: impl Into<String>,
        tokens: crate::ui::tokens::ThemeTokens,
    ) -> AnyElement {
        div()
            .flex()
            .items_center()
            .justify_between()
            .gap(px(tokens.density.spacing.md))
            .py(px(tokens.density.spacing.xs))
            .text_size(px(tokens.density.typography.caption))
            .line_height(px(tokens.density.typography.caption_line_height))
            .child(
                div()
                    .flex_none()
                    .text_color(tokens.text.muted.to_gpui())
                    .child(label),
            )
            .child(
                div()
                    .flex_1()
                    .min_w(px(0.0))
                    .truncate()
                    .text_right()
                    .font_weight(FontWeight::MEDIUM)
                    .text_color(tokens.text.primary.to_gpui())
                    .child(value.into()),
            )
            .into_any_element()
    }

