    fn inbox_agent_header_actions_static(&self) -> Option<AnyElement> {
        if self.first_workspace_project_id().is_none() {
            return None;
        }
        let actions = inbox_agent_actions(self.agent_connection.as_ref()?);
        (!actions.is_empty()).then(|| {
            div()
                .flex()
                .flex_none()
                .items_center()
                .gap(px(self.theme_tokens().density.spacing.xs))
                .children(actions.into_iter().map(|action| {
                    Button::new(Self::inbox_agent_action_id(action.provider))
                        .label(action.label)
                        .ghost()
                        .into_any_element()
                }))
                .into_any_element()
        })
    }

    fn inbox_agent_header_actions(&self, cx: &Context<Self>) -> Option<AnyElement> {
        if self.first_workspace_project_id().is_none() {
            return None;
        }
        let actions = inbox_agent_actions(self.agent_connection.as_ref()?);
        (!actions.is_empty()).then(|| {
            div()
                .flex()
                .flex_none()
                .items_center()
                .gap(px(self.theme_tokens().density.spacing.xs))
                .children(actions.into_iter().map(|action| {
                    let provider = action.provider;
                    Button::new(Self::inbox_agent_action_id(provider))
                        .label(action.label)
                        .ghost()
                        .on_click(cx.listener(move |shell, _event: &ClickEvent, _window, cx| {
                            cx.stop_propagation();
                            shell.start_task_with_agent(provider);
                            cx.notify();
                        }))
                        .into_any_element()
                }))
                .into_any_element()
        })
    }

    fn conversation_delete_action(&self, cx: &Context<Self>) -> Option<AnyElement> {
        let tokens = self.theme_tokens();
        let selected = self.interaction.selected_task();
        let selected_lifecycle = selected.and_then(|task_id| {
            self.client_model
                .as_ref()
                .and_then(|model| model.tasks().get(&task_id))
                .map(|snapshot| snapshot.task.lifecycle)
        });
        let selected_is_settled =
            selected_lifecycle == Some(crate::domain::task::TaskLifecycle::Settled);
        let selected_is_archived =
            selected_lifecycle == Some(crate::domain::task::TaskLifecycle::Archived);
        let done = selected
            .filter(|_| !selected_is_settled && !selected_is_archived)
            .map(|_| {
                div()
                    .id("native-task-settle")
                    .tab_stop(true)
                    .h(px(26.0))
                    .flex()
                    .items_center()
                    .gap(px(6.0))
                    .px(px(10.0))
                    .rounded(px(6.0))
                    .cursor_pointer()
                    .bg(tokens.surfaces.raised.to_gpui())
                    .text_size(px(tokens.density.typography.caption))
                    .text_color(tokens.text.secondary.to_gpui())
                    .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
                    .on_click(cx.listener(|shell, _event: &ClickEvent, _window, cx| {
                        cx.stop_propagation();
                        shell.settle_selected_task();
                        cx.notify();
                    }))
                    .child(crate::icons::app_icon(
                        crate::icons::CHECK,
                        12.0,
                        tokens.text.secondary.to_u32(),
                    ))
                    .child("Done")
                    .into_any_element()
            });
        let restore = selected
            .filter(|_| selected_is_settled || selected_is_archived)
            .map(|task_id| {
                div()
                    .id("native-task-restore")
                    .tab_stop(true)
                    .h(px(26.0))
                    .flex()
                    .items_center()
                    .gap(px(6.0))
                    .px(px(10.0))
                    .rounded(px(6.0))
                    .cursor_pointer()
                    .bg(tokens.surfaces.raised.to_gpui())
                    .text_size(px(tokens.density.typography.caption))
                    .text_color(tokens.text.secondary.to_gpui())
                    .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
                    .on_click(cx.listener(move |shell, _event: &ClickEvent, _window, cx| {
                        cx.stop_propagation();
                        shell.reopen_task(task_id);
                        cx.notify();
                    }))
                    .child(crate::icons::app_icon(
                        crate::icons::REFRESH_CW,
                        12.0,
                        tokens.text.secondary.to_u32(),
                    ))
                    .child("Restore")
                    .into_any_element()
            });
        let archive = selected.filter(|_| !selected_is_archived).map(|_| {
            div()
                .id("native-task-archive")
                .tab_stop(true)
                .h(px(26.0))
                .flex()
                .items_center()
                .gap(px(6.0))
                .px(px(10.0))
                .rounded(px(6.0))
                .cursor_pointer()
                .bg(tokens.surfaces.raised.to_gpui())
                .text_size(px(tokens.density.typography.caption))
                .text_color(tokens.text.muted.to_gpui())
                .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
                .on_click(cx.listener(|shell, _event: &ClickEvent, _window, cx| {
                    cx.stop_propagation();
                    shell.archive_selected_task();
                    cx.notify();
                }))
                .child(crate::icons::app_icon(
                    crate::icons::ARCHIVE,
                    12.0,
                    tokens.text.muted.to_u32(),
                ))
                .child("Archive")
                .into_any_element()
        });
        let delete = selected.map(|task_id| {
            div()
                .id("native-task-delete")
                .tab_stop(true)
                .h(px(26.0))
                .flex()
                .items_center()
                .gap(px(6.0))
                .px(px(10.0))
                .rounded(px(6.0))
                .cursor_pointer()
                .bg(tokens.surfaces.raised.to_gpui())
                .text_size(px(tokens.density.typography.caption))
                .text_color(tokens.status.destructive.to_gpui())
                .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
                .on_click(cx.listener(move |shell, _event: &ClickEvent, _window, cx| {
                    cx.stop_propagation();
                    shell.begin_task_delete(task_id);
                    cx.notify();
                }))
                .child(crate::icons::app_icon(
                    crate::icons::TRASH,
                    12.0,
                    tokens.status.destructive.to_u32(),
                ))
                .child("Delete")
                .into_any_element()
        });
        let add_action = {
            div()
                .id("native-shell-tools-affordance")
                .tab_stop(true)
                .h(px(26.0))
                .flex()
                .items_center()
                .gap(px(6.0))
                .px(px(10.0))
                .rounded(px(6.0))
                .cursor_pointer()
                .bg(tokens.surfaces.raised.to_gpui())
                .text_size(px(tokens.density.typography.caption))
                .text_color(tokens.text.secondary.to_gpui())
                .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
                .on_click(cx.listener(|shell, _event: &ClickEvent, _window, cx| {
                    cx.stop_propagation();
                    shell.open_project_action_menu();
                    cx.notify();
                }))
                .child(crate::icons::app_icon(
                    crate::icons::PLUS,
                    12.0,
                    tokens.text.secondary.to_u32(),
                ))
                .child("Add action")
                .into_any_element()
        };
        let commit = div()
            .id("native-task-commit")
            .tab_stop(true)
            .h(px(26.0))
            .flex()
            .items_center()
            .gap(px(6.0))
            .px(px(10.0))
            .rounded(px(6.0))
            .cursor_pointer()
            .bg(tokens.surfaces.raised.to_gpui())
            .text_size(px(tokens.density.typography.caption))
            .text_color(tokens.text.secondary.to_gpui())
            .hover(|style| style.bg(tokens.surfaces.overlay.to_gpui()))
            .on_click(cx.listener(|shell, _event: &ClickEvent, _window, cx| {
                cx.stop_propagation();
                shell.begin_header_commit();
                cx.notify();
            }))
            .child(crate::icons::app_icon(
                crate::icons::GIT_BRANCH,
                12.0,
                tokens.text.secondary.to_u32(),
            ))
            .child("Commit")
            .into_any_element();
        Some(
            div()
                .id("native-conversation-panel-actions")
                .flex()
                .items_center()
                .gap(px(self.theme_tokens().density.spacing.xs))
                .child(add_action)
                .child(commit)
                .children(done)
                .children(restore)
                .children(archive)
                .children(delete)
                .into_any_element(),
        )
    }

