    #[test]
    fn task_search_takes_focus_from_composer_and_accepts_text() {
        const TEST_NAME: &str =
            "ui::native_shell::tests::task_search_takes_focus_from_composer_and_accepts_text";
        if rerun_headless_shell_test_in_child(TEST_NAME) {
            return;
        }

        let completed = std::rc::Rc::new(std::cell::Cell::new(false));
        let completed_for_app = std::rc::Rc::clone(&completed);
        gpui::Application::new().run(move |cx| {
            crate::ui::init(cx);
            let workspace = tempfile::tempdir().expect("workspace tempdir");
            let profile = isolated_dev_profile(workspace.path()).expect("isolated profile");
            let (runtime, _) = TestRuntime::new(true, NativeHostActionResult::Queued);
            let (model, task_id) = terminal_bound_client_model_with_kind_provider_at_epoch(
                crate::domain::task::TaskAttention::None,
                crate::providers::ProviderKind::Codex,
                None,
                3,
            );
            let window = cx
                .open_window(
                    WindowOptions {
                        show: false,
                        ..WindowOptions::default()
                    },
                    move |window, cx| {
                        let entity = cx.new(|cx| {
                            NativeShell::new_with_host_runtime_port(
                                profile,
                                Box::new(runtime),
                                crate::ui::tokens::RuntimePreferencesSnapshot::default(),
                                cx,
                            )
                        });
                        entity.update(cx, |shell, _cx| {
                            shell
                                .apply_client_model(Arc::new(model))
                                .expect("apply model");
                            let list =
                                crate::ui::task_cockpit::TaskList::from_client_model_virtual(
                                    shell.client_model_snapshot().as_ref().expect("model"),
                                )
                                .expect("task list");
                            let _ = shell.interaction.navigation_mouse_down(task_id, &list);
                            shell.sync_cockpit_follow();
                            shell.composer_focus_handle.focus(window);
                        });
                        entity
                    },
                )
                .expect("open hidden task-search window");
            let entity = window.entity(cx).expect("task-search root entity");
            let any_window = window.into();

            entity.update(cx, |shell, cx| {
                shell.dispatch_keyboard_for_test(crate::ui::actions::KeyboardShortcut::ctrl(
                    crate::ui::actions::ShortcutKey::Character('p'),
                ));
                cx.notify();
            });
            cx.refresh_windows();

            cx.update_window(any_window, |_root, window, cx| {
                entity.update(cx, |shell, _cx| shell.focus_task_search_input(window));
                assert!(
                    entity.read(cx).task_search.open(),
                    "the task-search action must open the picker"
                );
                assert!(
                    entity.read(cx).root_editor_focus_handle.is_focused(window),
                    "opening search must transfer focus away from the composer"
                );
                assert!(
                    window.dispatch_keystroke(Keystroke::parse("d").expect("search key"), cx),
                    "printable input must reach the open task search"
                );
            })
            .expect("dispatch task-search keys");

            let shell = entity.read(cx);
            assert!(shell.task_search.open());
            assert_eq!(shell.task_search.query(), "d");
            let platform_input = shell
                .platform_accessibility_tree_for_test()
                .nodes
                .into_iter()
                .find_map(|(_, node)| {
                    (node.author_id() == Some("native-task-search-input")).then_some(node)
                })
                .expect("task search must expose a platform text field");
            assert_eq!(platform_input.role(), accesskit::Role::TextInput);
            assert_eq!(platform_input.value(), Some("d"));
            assert!(platform_input.supports_action(accesskit::Action::Focus));
            assert!(platform_input.supports_action(accesskit::Action::SetValue));

            completed_for_app.set(true);
            cx.quit();
        });
        assert!(completed.get(), "hidden task-search scenario completed");
    }

    #[test]
    fn printable_composer_keys_reach_the_platform_text_input_handler() {
        let source = include_str!("native_shell.rs");
        let listener_start = source
            .find("let key = cx.listener(|shell, event: &KeyDownEvent")
            .expect("composer key listener");
        let listener_end = source[listener_start..]
            .find("let send = cx.listener")
            .map(|offset| listener_start + offset)
            .expect("composer send listener after key listener");
        let listener = &source[listener_start..listener_end];
        assert!(
            !listener.contains("cx.stop_propagation()"),
            "the listener must let printable keys reach GPUI's WM_CHAR/IME input path"
        );
        assert!(
            source.contains("fn replace_text_in_range(")
                && source.contains("self.replace_composer_platform_text(range_utf16, text)"),
            "the registered EntityInputHandler must mutate the task draft"
        );
        assert!(
            source.contains("self.replace_root_platform_text(range_utf16, text)")
                && source.contains("root_input_registration")
                && source.contains("ElementInputHandler::new(bounds, input_proxy)")
                && source.contains("impl EntityInputHandler for RootEditorInputProxy")
                && source.contains(".children(root_input_registration)"),
            "root editors must own a distinct GPUI input entity and route platform text"
        );
        assert!(
            source.contains("native-rename-task-name")
                && source.contains("native-add-project-name")
                && source.contains("native-task-terminal-rows"),
            "rename, add-project, and task-terminal must expose AccessKit nodes"
        );
        assert!(
            source.contains("native-rename-task-submit")
                && source.contains("native-rename-task-cancel")
                && source.contains("pending_root_overlay_focus"),
            "rename submit/cancel and overlay Focus must stay wired through AccessKit"
        );
        assert!(
            source.contains("native-empty-conversation") && source.contains("No messages yet"),
            "valid empty timelines must show an honest empty conversation state"
        );
    }

    #[test]
    fn honest_empty_conversation_requires_live_projection_with_zero_rows() {
        let source = include_str!("native_shell.rs");
        assert!(
            source.contains("fn honest_empty_conversation("),
            "empty conversation gate must remain fail-closed to live projection + zero rows"
        );
        let empty_branch = source
            .split("if self.honest_empty_conversation()")
            .nth(1)
            .and_then(|tail| tail.split("} else {").next())
            .expect("honest empty conversation render branch");
        assert!(
            empty_branch.contains("native-task-conversation-surface")
                && empty_branch.contains("native-empty-conversation")
                && empty_branch.contains(".child(composer_footer)"),
            "zero-row conversations must keep the canonical surface + composer/footer contract"
        );
    }

